CREATE DATABASE IF NOT EXISTS student_assignment_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_assignment_system;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(30) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','teacher') NOT NULL DEFAULT 'student', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assignments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, teacher_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, subject VARCHAR(100) NOT NULL, description TEXT NOT NULL, due_date DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_assignments_teacher FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS submissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assignment_id INT UNSIGNED NOT NULL, student_id INT UNSIGNED NOT NULL, answer_text TEXT NOT NULL, submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, marks DECIMAL(5,2) NULL, feedback TEXT NULL, UNIQUE KEY unique_student_assignment (assignment_id, student_id), CONSTRAINT fk_submissions_assignment FOREIGN KEY (assignment_id) REFERENCES assignments(id) ON DELETE CASCADE, CONSTRAINT fk_submissions_student FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE);
